// Build a readable summary line for this attendance row
const row = context.item.data;
if (!row) return '';
const role = row.role ? (row.role.charAt(0).toUpperCase() + row.role.slice(1)) : 'User #' + row.user_id;
const joined = row.join_time ? new Date(row.join_time).toLocaleString() : 'never joined';
const left = row.leave_time ? new Date(row.leave_time).toLocaleString() : 'still in / not recorded';
const talkMin = row.talk_seconds ? Math.round(row.talk_seconds / 60 * 10) / 10 : 0;
return role + ' — joined: ' + joined + ' — left: ' + left + ' — talked: ' + talkMin + ' min';

