const a = variables['d88c3438-58a4-470d-9cf4-03104ea8ec6d'];
const slots = a?.availability || [];
if (!slots.length) return 'No availability submitted.';
const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const byDay = {};
slots.forEach(s => {
  const d = s.day_of_week;
  if (!byDay[d]) byDay[d] = [];
  byDay[d].push(s.start_time + '-' + s.end_time);
});
return Object.keys(byDay).sort((a,b)=>a-b).map(d => dayNames[d] + ': ' + byDay[d].join(', ')).join('\n');

